import { requireAdmin } from "@/lib/auth"; import { db } from "@/lib/db"; import { fail, handleApiError, ok } from "@/lib/http";
export const dynamic = "force-dynamic";
export async function GET(_: Request, { params }: { params: { id: string } }) { try { await requireAdmin(); const item = await db.vendor.findUnique({ where: { id: params.id }, include: { addedBy: { select: { id: true, name: true, trustScore: true } }, claimedBy: { select: { id: true, name: true } }, reviews: { orderBy: { createdAt: "desc" }, include: { user: { select: { id: true, name: true, trustScore: true, isTrustedContributor: true } } } }, photos: { orderBy: { createdAt: "desc" }, include: { user: { select: { id: true, name: true } } } }, reports: { orderBy: { createdAt: "desc" }, include: { user: { select: { id: true, name: true } } } } } }); if (!item) return fail("Vendor not found", 404); const activity = await db.activityLog.findMany({ where: { entityType: "vendor", entityId: params.id }, orderBy: { createdAt: "desc" }, include: { user: { select: { name: true, role: true } } } }); return ok({ ...item, activity }); } catch (error) { return handleApiError(error); } }
